        if (rval instanceof RVal.Binop binop) {
            AbstractValue l = eval(binop.l(), state);
            AbstractValue r = eval(binop.r(), state);
            if (l.isBottom() || r.isBottom()) return AbstractValue.BOTTOM;
            return evalBinop(binop.op(), l, r);
