            State pre = state;
            // If target is Zero, one operand must be Zero.
            // We can't know which. So both can be Top?
            // But if target is NonZero, both must be NonZero.
            AbstractValue lVal = eval(binop.l(), state);
            AbstractValue rVal = eval(binop.r(), state);
