    }

    private Sign fromValue(BigInteger v) {
        int cmp = v.compareTo(ZERO);
        if (cmp == 0) return Sign.ZERO;
        if (cmp > 0) return Sign.POS;
        return Sign.NEG;
    }

    private Sign addSign(Sign l, Sign r) {
        if (l == Sign.ZERO) return r;
        if (r == Sign.ZERO) return l;
        if (l == Sign.POS && r == Sign.POS) return Sign.POS;
        if (l == Sign.NEG && r == Sign.NEG) return Sign.NEG;
        if (l == Sign.POS && r == Sign.NEG) return Sign.TOP;
        if (l == Sign.NEG && r == Sign.POS) return Sign.TOP;
        return Sign.TOP;
    }

    private Sign subSign(Sign l, Sign r) {
        if (r == Sign.ZERO) return l;
        if (l == Sign.ZERO) return negateSign(r);
        if (l == Sign.POS && r == Sign.POS) return Sign.TOP;
        if (l == Sign.NEG && r == Sign.NEG) return Sign.TOP;
        if (l == Sign.POS && r == Sign.NEG) return Sign.POS;
        if (l == Sign.NEG && r == Sign.POS) return Sign.NEG;
        return Sign.TOP;
    }

    private Sign multSign(Sign l, Sign r) {
        if (l == Sign.ZERO || r == Sign.ZERO) return Sign.ZERO;
        if (l == Sign.POS) return r;
        if (l == Sign.NEG) return negateSign(r);
        if (r == Sign.POS) return l;
        if (r == Sign.NEG) return negateSign(l);
        return Sign.TOP;
    }

    private Sign negateSign(Sign s) {
        if (s == Sign.ZERO) return Sign.ZERO;
        if (s == Sign.POS) return Sign.NEG;
        if (s == Sign.NEG) return Sign.POS;
        if (s == Sign.NONZERO) return Sign.NONZERO;
        if (s == Sign.NONPOS) return Sign.NONNEG;
        if (s == Sign.NONNEG) return Sign.NONPOS;
        return Sign.TOP;
    }
